<script lang="ts">import { onMount } from 'svelte';import { goto } from '$app/navigation';import { getMe,updateMe,updatePhoto,changePassword } from '../../features/users/api/usersApi';import { logout } from '../../features/auth/api/authApi';import { GraduationCap } from 'lucide-svelte';let profile=$state<any>({});let name=$state('');let email=$state('');let oldPassword=$state('');let newPassword=$state('');let error=$state('');let message=$state('');onMount(async()=>{try{const r:any=await getMe();profile=r?.data?.user||r?.data||{};name=profile.name||'';email=profile.email||'';}catch(e){error=e instanceof Error?e.message:'Gagal memuat profil';}});async function save(){try{await updateMe({name,email});message='Profil berhasil diperbarui';}catch(e){error=e instanceof Error?e.message:'Gagal menyimpan profil';}}async function photo(e:Event){const f=(e.currentTarget as HTMLInputElement).files?.[0];if(f)try{await updatePhoto(f);message='Foto berhasil diperbarui';}catch(x){error=x instanceof Error?x.message:'Gagal memperbarui foto';}}async function password(){try{await changePassword(oldPassword,newPassword);message='Password berhasil diubah';oldPassword='';newPassword='';}catch(e){error=e instanceof Error?e.message:'Gagal mengubah password';}}</script><div class="shell"><header class="topbar"><a class="brand" href="/"><GraduationCap/> Delcom <b>Courses</b></a><nav><a href="/">Semua Kursus</a><a href="/users">Pengguna</a><button class="text-button" onclick={async()=>{logout();await goto('/auth/login');}}>Keluar</button></nav></header><main class="container profile-page"><h1>Profil saya</h1>{#if error}<div class="alert">{error}</div>{/if}{#if message}<div class="success">{message}</div>{/if}<section class="panel"><h2>Informasi akun</h2><label>Nama<input bind:value={name}/></label><label>Email<input type="email" bind:value={email}/></label><button class="primary" onclick={save}>Simpan profil</button><label>Foto profil<input type="file" accept="image/*" onchange={photo}/></label></section><section class="panel"><h2>Ubah password</h2><label>Password lama<input type="password" bind:value={oldPassword}/></label><label>Password baru<input type="password" bind:value={newPassword} minlength="6"/></label><button class="primary" onclick={password}>Ubah password</button></section></main></div>